window.NPC_CHUNK_84 = [{"name":"Ezren Level 12","cr":12,"xp":19200,"race":"human","age_category":"Adult","classes":[{"class":"wizard","level":12}],"alignment":"N","size":"Medium","type":"humanoid","sub_types":["human"],"init":2,"ac":24,"ac_touch":14,"ac_flat_footed":22,"ac_mods":"+4 armor, +2 deflection, +2 Dex, +2 natural, +4 shield","hp":92,"hd":"12d6+48","hd_value":12,"fort":11,"ref":9,"will":12,"speed":[{"type":"land","speed":30}],"melee":"+2 cane (rod of thunder and lightning) +8 (1d6+2) or dagger +6 (1d4/19-20)","ranged":"mwk light crossbow +9 (1d8/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"hand of the apprentice","details":"10/day"},{"type":"metamagic mastery","details":"3/day"}],"spellsprepared_caster":"wizard","spellsprepared_caster_level":12,"spellsprepared_concentration":19,"spellsprepared":[{"spell_level":6,"spell_slots":3,"spells":[{"spell":"disintegrate"},{"spell":"greater dispel magic"},{"spell":"summon monster VI"}]},{"spell_level":5,"spell_slots":4,"spells":[{"spell":"cloudkill"},{"spell":"cone of cold"},{"spell":"empowered lightning bolt"},{"spell":"teleport"}]},{"spell_level":4,"spell_slots":4,"spells":[{"spell":"dimension door"},{"spell":"greater invisibility"},{"spell":"scrying"},{"spell":"shout"}]},{"spell_level":3,"spell_slots":6,"spells":[{"spell":"dispel magic"},{"spell":"fireball"},{"spell":"fly"},{"spell":"haste"},{"spell":"lightning bolt"},{"spell":"tongues"}]},{"spell_level":2,"spell_slots":6,"spells":[{"spell":"acid arrow"},{"spell":"glitterdust"},{"spell":"knock"},{"spell":"scorching ray","count":2},{"spell":"spider climb"}]},{"spell_level":1,"spell_slots":10,"spells":[{"spell":"burning hands"},{"spell":"charm person"},{"spell":"expeditious retreat"},{"spell":"grease"},{"spell":"mage armor"},{"spell":"magic missile"},{"spell":"obscuring mist"},{"spell":"protection from evil"},{"spell":"shield","count":2}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"acid splash"},{"spell":"detect magic"},{"spell":"light"},{"spell":"mage hand"}]}],"strength":10,"dexterity":14,"constitution":14,"intelligence":24,"wisdom":12,"charisma":10,"baseatk":6,"cmb":6,"cmd":20,"feats":[{"feat":"Combat Casting"},{"feat":"Craft Magic Arms and Armor"},{"feat":"Craft Rod"},{"feat":"Empower Spell"},{"feat":"Great Fortitude"},{"feat":"Greater Spell Focus (evocation)"},{"feat":"Scribe Scroll"},{"feat":"Spell Focus (evocation)"},{"feat":"Spell Penetration"},{"feat":"Toughness"}],"skills":[{"skill":"Appraise","value":22},{"skill":"Craft (alchemy)","value":22},{"skill":"Fly","value":17},{"skill":"Knowledge (arcana)","value":22},{"skill":"Knowledge (engineering)","value":22},{"skill":"Knowledge (history)","value":22},{"skill":"Knowledge (nature)","value":22},{"skill":"Knowledge (planes)","value":22},{"skill":"Linguistics","value":22},{"skill":"Spellcraft","value":22}],"languages":["Common","Abyssal","Aklo","Aquan","Auran","Azlanti","Celestial","Draconic","Dwarven","Elven","Giant","Gnoll","Goblin","Ignan","Infernal","Kelish","Orc","Osiriani","Terran","Undercommon"],"sq":["arcane bond (cane)"],"gear":"+2 cane (rod of thunder and lightning; treat as club), dagger, masterwork light crossbow with 10 bolts, amulet of natural armor +2, cloak of resistance +3, headband of vast intelligence +4, ring of protection +2, ring of wizardry I, backpack, scroll case, spell component pouch, spellbook (contains all prepared spells plus all 0-level spells; 1st-color spray, sleep; 2nd-bear's endurance; 4th-black tentacles, summon monster IV; 5th-dream, polymorph, mage's private sanctum; 6th-true seeing), 724 gp, potion of cat's grace, potions of cure serious wounds (3), scroll of antimagic field, scroll of passwall, scrolls of protection from energy (2), scroll of remove curse, scroll of secure shelter, staff of fire, wand of mnemonic enhancer (7 charges)","before_combat":"Ezren casts mage armor and shield before the start of the encounter. Given the time, he also casts fly and greater invisibility.","during_combat":"Ezren uses his attack spells in conjunction with his hand of the apprentice special attack to eliminate threats against him and his companions.","base_statistics":"Without mage armor and shield, Ezren's statistics are AC 16, touch 14, flat-footed 14.","source":"NPC Codex"},{"name":"Pym, Shor, And Vosi","cr":0.5,"xp":200,"race":"sprite","gender":"Male","age_category":"Adult","classes":[{"class":"fighter","level":1}],"alignment":"CE","size":"Diminutive","type":"fey","sub_types":["cold"],"templates_applied":"winter-touched","init":3,"senses":["detect evil","detect good","low-light vision"],"ac":17,"ac_touch":17,"ac_flat_footed":14,"ac_mods":"+3 Dex, +4 size","hp":10,"hd":"1d6+1d10+2","hd_value":2,"fort":3,"ref":5,"will":1,"dr":"2/cold iron","immunities":["cold"],"weaknesses":["vulnerable to fire"],"speed":[{"type":"fly","speed":60,"maneuverability":"perfect"},{"type":"land","speed":15}],"melee":"short sword +3 (1d2-2/19-20 plus numbing cold)","ranged":"shortbow +8 (1d2-2/x3 plus numbing cold)","space":"1 ft.","reach":"0 ft.","special_attacks":[{"type":"numbing cold","details":"DC 11"}],"spell_like_abilities_caster_level":5,"spell_like_abilities_concentration":6,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"detect evil"},{"spell":"detect good"}]},{"frequency":"at-will","spells":[{"spell":"dancing lights"},{"spell":"daze"}]},{"frequency":"1/day","spells":[{"spell":"color spray"}]}],"strength":7,"dexterity":16,"constitution":12,"intelligence":10,"wisdom":8,"charisma":13,"baseatk":1,"cmb":0,"cmd":8,"feats":[{"feat":"Alertness"},{"feat":"Deadly Aim"}],"skills":[{"skill":"Escape Artist","value":15},{"skill":"Fly","value":21},{"skill":"Perception","value":6},{"skill":"Sense Motive","value":5},{"skill":"Stealth","value":20},{"skill":"Survival","value":4}],"languages":["Common","Sylvan"],"sq":["luminous"],"gear":"short sword, shortbow with 20 arrows, 14 gp","during_combat":"Initially, the sprites snipe at the PCs while hiding in the trees. After firing, they can attempt another Stealth check at a -20 penalty to stay hidden. If anyone closes on their position, the sprites forgo further attacks until they can silently relocate to another tree. Any sprite spotted by the PCs fights defensively to protect itself, drawing the PCs' attention so its companions can sneak up behind the PCs and catch their enemies in a color spray. They take turns with this tactic to blind, stun, and knock out as many targets as possible, then rain arrows infused with numbing cold on those who remain.","morale":"If the sprites are faced with fire-based attacks or the PCs manage to slay the majority of them, the remaining sprites flee, seeking out Fawfein (at area E) or Izoze (at area H4) for protection. They cast dancing lights once more to mask their retreat, sending the lights in different directions as they dim their own luminosity in the hope of leading pursuers astray.","source":"AP 67, Pathfinder RPG Bestiary 3 256 and page 72"},{"name":"Rohkar's Raiders","cr":0.3333,"xp":135,"race":"human","age_category":"Adult","classes":[{"class":"warrior","level":1}],"alignment":"CE","size":"Medium","type":"humanoid","sub_types":["human"],"init":1,"ac":13,"ac_touch":11,"ac_flat_footed":12,"ac_mods":"+1 armor, +1 Dex, +1 shield","hp":7,"hd":"1d10+2","hd_value":1,"fort":3,"ref":1,"will":-1,"speed":[{"type":"land","speed":30}],"melee":"short sword +3 (1d6+1/19-20)","ranged":"shortbow +2 (1d6/x3)","space":"5 ft.","reach":"5 ft.","strength":13,"dexterity":13,"constitution":12,"intelligence":10,"wisdom":9,"charisma":8,"baseatk":1,"cmb":2,"cmd":13,"feats":[{"feat":"Skill Focus (Stealth)"},{"feat":"Weapon Focus (short sword)"}],"skills":[{"skill":"Intimidate","value":3},{"skill":"Perception","value":0},{"skill":"Stealth","value":4}],"languages":["Common"],"gear":"padded armor, buckler, short sword, shortbow with 20 arrows, 8 gp, 5 sp","during_combat":"If able to prepare an ambush, the bandits fire on the most heavily armored opponents first, hoping to wound them before engaging in melee. Thereafter, they drop their bows, draw their swords, and charge.","morale":"If overmatched or caught by surprise, the bandits withdraw, believing the Taldan authorities have come to avenge Lady Argentea's abduction. Fighting defensively, they separate to put distance between themselves, covering each other with their bows, while they try to make it back to the lodge to warn the bandits of the PCs' presence. If pinned down (or flanked), they draw their swords and fight.","source":"AP 67"},{"name":"Ten-Penny Tacey","cr":2,"xp":600,"race":"half-Orc","gender":"Female","age_category":"Adult","classes":[{"class":"rogue","level":3}],"alignment":"CN","size":"Medium","type":"humanoid","sub_types":["human","Orc"],"init":7,"senses":["darkvision 60 ft."],"ac":15,"ac_touch":13,"ac_flat_footed":12,"ac_mods":"+2 armor, +3 Dex","hp":20,"hd":"3d8+3","hd_value":3,"fort":2,"ref":6,"will":0,"save_mods":"Ref: +1 vs. traps","defensive_abilities":["evasion","Orc ferocity","trap sense +1"],"speed":[{"type":"land","speed":30}],"melee":"short sword +5 (1d6+2/19-20)","ranged":"mwk hand crossbow +6 (1d4/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"sneak attack","details":"+2d6"}],"strength":14,"dexterity":17,"constitution":12,"intelligence":10,"wisdom":8,"charisma":13,"baseatk":2,"cmb":4,"cmd":17,"feats":[{"feat":"Improved Initiative"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":9},{"skill":"Appraise","value":4},{"skill":"Bluff","value":7},{"skill":"Climb","value":10},{"skill":"Disable Device","value":10},{"skill":"Intimidate","value":9},{"skill":"Knowledge (local)","value":6},{"skill":"Perception","value":5},{"skill":"Sleight of Hand","value":9},{"skill":"Stealth","value":9}],"languages":["Common","Goblin","Orc"],"sq":["Orc blood","rogue talents (surprise attack)","trapfinding +1","weapon familiarity"],"gear":"leather armor, dagger, mwk hand crossbow with 12 bolts, short sword, climber's kit, crowbar, grappling hook, key to chest in area H12, mwk thieves' tools, silk rope (50 ft.), 28 gp, elixir of hiding, potion of invisibility, potion of pass without trace, potion of spider climb, tanglefoot bag","during_combat":"Ten-Penny makes no effort to slay the PCs, focusing purely on fighting defensively, though she takes advantage of opportunities to make sneak attacks.","morale":"Ten-Penny had little to do with Lady Argentea's abduction and doesn't wish to die for Rohkar's crimes. If reduced to 5 hit points or fewer, she pleads for quarter, claiming no solidarity with the bandits as she surrenders.","source":"AP 67"},{"name":"Rohkar Cindren","cr":2,"xp":600,"race":"human","gender":"Male","age_category":"Adult","classes":[{"class":"cleric of Norgorber","level":3}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":2,"ac":16,"ac_touch":12,"ac_flat_footed":14,"ac_mods":"+3 armor, +2 Dex, +1 natural","hp":20,"hd":"3d8+3","hd_value":3,"fort":2,"ref":3,"will":5,"speed":[{"type":"land","speed":30}],"melee":"+1 short sword +5 (1d6+2/19-20 plus greenblood oil) or dagger +4 (1d4+1/19-20)","ranged":"light crossbow +4 (1d8/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel negative energy","details":"5/day, DC 13, 2d6"}],"spell_like_abilities_caster_level":3,"spell_like_abilities_concentration":5,"spell_like_abilities":[{"frequency":"5/day","spells":[{"spell":"bleeding touch","details":"1 round"},{"spell":"copycat","details":"3 rounds"}]}],"spellsprepared_caster":"cleric","spellsprepared_caster_level":3,"spellsprepared_concentration":5,"spellsprepared":[{"spell_level":2,"spell_slots":3,"spells":[{"spell":"death knell"},{"spell":"hold person"},{"spell":"invisibility","type":"domain"}]},{"spell_level":1,"spell_slots":4,"spells":[{"spell":"cause fear","type":"domain"},{"spell":"deathwatch"},{"spell":"magic weapon"},{"spell":"murderous command"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"detect poison"},{"spell":"purify food and drink"},{"spell":"resistance"}]}],"spelldomains":"Death, Trickery","strength":13,"dexterity":14,"constitution":8,"intelligence":10,"wisdom":15,"charisma":14,"baseatk":2,"cmb":3,"cmd":15,"feats":[{"feat":"Deft Hands"},{"feat":"Toughness"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Bluff","value":6},{"skill":"Disable Device","value":7},{"skill":"Disguise","value":6},{"skill":"Intimidate","value":3},{"skill":"Knowledge (local)","value":1},{"skill":"Sense Motive","value":6},{"skill":"Sleight of Hand","value":5},{"skill":"Stealth","value":6},{"skill":"Use Magic Device","value":3}],"languages":["Common"],"gear":"mwk studded leather, dagger, light crossbow with 10 bolts, mwk short sword, cloak of the yeti, mwk thieves' tools, ring of keys (key to trap door in area H7, chest in H11, and cage in area H16), stolen spellbook (contains alarm, chill touch, expeditious retreat, feather fall, identify, locate object, and ray of enfeeblement), wooden unholy symbol of Norgorber, 15 gp, scroll of animate dead (10 HD), greenblood oil (1), oil of taggit (2)","before_combat":"If alerted to the PCs' presence in the lodge, Rohkar casts deathwatch, invisibility, and magic weapon. He also applies greenblood oil to his short sword.","during_combat":"Rohkar invisibly exits the room when the PCs arrive, squeezing past anyone at the door while his frost skeletons occupy them. If he finds any bandits unconscious or dying, Rohkar slays them with death knell to further empower himself, then uses his scroll of animate dead to create zombies from their bodies. Upon returning, he directs the undead while channeling negative energy to heal them. If faced with a cleric channeling positive energy, he counters with cause fear and his poisoned blade, activating his copycat ability to confuse anyone striking back.","morale":"Rohkar lives to kill in the name of Norgorber, but has no desire to die himself. If reduced to 5 hit points or fewer, he throws down his weapon and feigns remorse, blaming everything on Izoze and Teb Knotten.","source":"AP 67"},{"name":"Thora Petska","cr":3,"xp":800,"race":"guardian doll","gender":"Female","age_category":"Adult","alignment":"NE","size":"Tiny","type":"construct","sub_types":["cold"],"init":7,"senses":["darkvision 60 ft.","low-light vision"],"ac":16,"ac_touch":15,"ac_flat_footed":13,"ac_mods":"+3 Dex, +1 natural, +2 size","hp":22,"hd":"4d10","hd_value":4,"fort":1,"ref":4,"will":2,"dr":"5/magic","immunities":["cold","construct traits"],"sr":14,"weaknesses":["susceptible to mind-affecting effects","vulnerable to fire"],"speed":[{"type":"land","speed":30}],"melee":"doll's dagger +10 (1d2-1/19-20 plus 1d6 cold and paralysis)","space":"5 ft.","reach":"5 ft.","spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":4,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"ray of frost"}]},{"frequency":"1/day","spells":[{"spell":"frost fall"},{"spell":"levitate"}]},{"frequency":"3/day","spells":[{"spell":"alarm"},{"spell":"charm person"},{"spell":"light"},{"spell":"mage hand"},{"spell":"open/ close"},{"spell":"prestidigitation"}]}],"strength":8,"dexterity":17,"intelligence":13,"wisdom":12,"charisma":10,"baseatk":4,"cmb":5,"cmd":11,"feats":[{"feat":"Improved Initiative"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Escape Artist","value":5},{"skill":"Linguistics","value":3},{"skill":"Perception","value":5},{"skill":"Stealth","value":15}],"languages":["Common","Hallit","Skald"],"sq":["soul focus"],"special_abilities":[{"type":"Doll's Dagger","kind":"Su","details":"The dagger wielded by a guardian doll is treated as a masterwork weapon and deals 1d6 points of cold damage in addition to its normal damage. Those struck by the dagger must succeed at a DC 12 Fortitude save or be paralyzed by the supernatural cold of the weapon for 1d4 rounds. If the guardian doll is destroyed, its weapon becomes a useless child's toy. The save DC is Charisma-based."},{"type":"Soul Focus","kind":"Su","details":"Thora's soul is bound within the doll's gemstone eye. As long as this soul focus remains intact, it can be used to animate another doll, using the same cost as creating a new construct. Once bound into the soul focus, the soul continues to learn. If it is put into a new doll body, the soul retains its personality and memories from its previous bodies. A soul focus has hardness 8, 12 hit points, and a break DC of 20."},{"type":"Susceptible to Mind-Affecting Effects","kind":"Ex","details":"Like a soulbound doll, a guardian doll is susceptible to mind-affecting effects. However, because of the singular purpose with which it is imbued, its saves against such effects are made with a +1 racial bonus."}],"during_combat":"Thora casts levitate to rise into the air so she can more safely cast spells, using charm person to create allies to prevent others from attacking her. If forced into melee combat, she casts frostfall and then attacks with her doll's dagger, hoping to catch paralyzed opponents in the supernaturally chilled area of the spell.","morale":"Thora fights until destroyed.","source":"AP 67, Pathfinder Campaign Setting: Irrisen, Land of Winter 58"},{"name":"Hommelstaub","cr":2,"xp":600,"race":"atomie","gender":"Male","age_category":"Adult","classes":[{"class":"oracle","level":2}],"alignment":"CE","size":"Diminutive","type":"fey","sub_types":["cold"],"templates_applied":"winter-touched","init":6,"senses":["low-light vision"],"ac":16,"ac_touch":16,"ac_flat_footed":14,"ac_mods":"+2 Dex, +4 size","hp":24,"hd":"2d6+2d8+8","hd_value":4,"fort":2,"ref":5,"will":9,"dr":"2/cold iron","immunities":["cold"],"resists":["fire 10"],"weaknesses":["vulnerable to fire"],"speed":[{"type":"fly","speed":50,"maneuverability":"good"},{"type":"land","speed":15}],"melee":"sickle +8 (1d2 plus numbing cold) or wintry touch +8 (1d6+1 cold)","ranged":"sling with magic stone +9 (1d6+1 plus numbing cold) or sling +8 (1 plus numbing cold)","space":"1 ft.","reach":"0 ft.","special_attacks":[{"type":"numbing cold","details":"DC 13"},{"type":"sneak attack","details":"+1d6"}],"spell_like_abilities_caster_level":6,"spell_like_abilities_concentration":10,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"speak with animals"}]},{"frequency":"at-will","spells":[{"spell":"dancing lights"},{"spell":"reduce person"}]},{"frequency":"1/day","spells":[{"spell":"shrink item"}]},{"frequency":"3/day","spells":[{"spell":"invisibility","details":"self only"}]}],"spellsknown_caster":"oracle","spellsknown_caster_level":2,"spellsknown_concentration":6,"spellsknown":[{"spell_level":1,"spell_slots":5,"spells":[{"spell":"endure elements"},{"spell":"inflict light wounds"},{"spell":"magic stone"},{"spell":"summon monster I"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"detect magic"},{"spell":"guidance"},{"spell":"read magic"},{"spell":"resistance"}]}],"mystery":"winterPOTN","strength":10,"dexterity":14,"constitution":15,"intelligence":15,"wisdom":16,"charisma":18,"baseatk":2,"cmb":0,"cmd":10,"feats":[{"feat":"Extra Revelation"},{"feat":"Improved Initiative","type":"bonus"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":8,"special":"-4 when jumping"},{"skill":"Bluff","value":8},{"skill":"Escape Artist","value":8},{"skill":"Fly","value":18},{"skill":"Intimidate","value":10},{"skill":"Knowledge (nature)","value":6},{"skill":"Perception","value":10},{"skill":"Sense Motive","value":8},{"skill":"Spellcraft","value":9},{"skill":"Stealth","value":20},{"skill":"Survival","value":8},{"skill":"Use Magic Device","value":8}],"languages":["Common","Abyssal","Giant","Sylvan; speak with animals"],"sq":["oracle's curse (lame)","revelations (snow sight, wintry touch 7/day [1d6+1 cold])"],"special_abilities":[{"type":"Snow Sight","kind":"Su","details":"Hommelstaub can see through falling snow and sleet without taking any penalties on Perception checks as long as he there is enough light for him to see normally."},{"type":"Wintry Touch","kind":"Su","details":"As a standard action 7 times per day, Hommelstaub can perform a melee touch attack that deals 1d6+1 points of cold damage."}],"gear":"sickle, sling, 64 gp, potion of cure moderate wounds, scroll of remove curse, scroll of resist energy (fire), liquid ice (3), thunderstones (2)","before_combat":"If he has time to prepare, Hommelstaub uses his scroll of resist energy and casts magic stone on three pebbles to hurl with his sling.","during_combat":"Hommelstaub turns invisible and flies upward to hide in the falling snow, where his snow sight grants him a superior view of the camp. He then throws a thunderstone, smashing it against an armored enemy or the side of an igloo to deafen his opponents and warn Teb Knotten and his sprite allies. Hommelstaub hurls bottles of liquid ice to snuff out any enemy fire sources, and casts summon monster I to summon fiendish eagles to attack opponents while he uses his sling. If drawn into melee combat, Hommelstaub casts reduce person on his attackers before making sneak attacks with inflict light wounds or his wintry touch.","morale":"If reduced to fewer than 15 hit points, Hommelstaub retreats back into the falling snow to drink his potion of cure moderate wounds. Thereafter, he fights to the death, though if Teb Knotten is dead, he might try to flee through the winter portal back to Irrisen instead.","source":"AP 67, Pathfinder RPG Bestiary 3 28, Pathfinder RPG Advanced Player's Guide 42, and page 72"},{"name":"Mierul Ardelain","cr":3,"xp":800,"race":"forlarren","gender":"Female","age_category":"Adult","classes":[{"class":"bard","level":2}],"alignment":"NE","size":"Medium","type":"fey","sub_types":["cold"],"templates_applied":"winter-touched","init":3,"senses":["low-light vision"],"ac":16,"ac_touch":13,"ac_flat_footed":13,"ac_mods":"+3 Dex, +3 natural","hp":29,"hd":"4d6+2d8+6","hd_value":6,"fort":2,"ref":10,"will":7,"dr":"5/cold iron","immunities":["cold"],"weaknesses":["remorse","vulnerable to fire"],"speed":[{"type":"land","speed":30}],"melee":"2 claws +6 (1d6+2 plus numbing cold) or flame blade +5 touch (1d8+2 fire plus numbing cold)","ranged":"light crossbow +6 (1d8/19-20 plus numbing cold)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"bardic performance 7 rounds/day","details":"countersong, distraction, fascinate, inspire courage +1"},{"type":"numbing cold","details":"DC 13"}],"spell_like_abilities_caster_level":4,"spell_like_abilities_concentration":5,"spell_like_abilities":[{"frequency":"3/day","spells":[{"spell":"flame blade"}]}],"spellsknown_caster":"bard","spellsknown_caster_level":2,"spellsknown_concentration":3,"spellsknown":[{"spell_level":1,"spell_slots":3,"spells":[{"spell":"chord of shards"},{"spell":"disguise self"},{"spell":"ear-piercing scream"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"dancing lights"},{"spell":"detect magic"},{"spell":"ghost sound"},{"spell":"prestidigitation"},{"spell":"summon instrument"}]}],"strength":14,"dexterity":17,"constitution":12,"intelligence":8,"wisdom":10,"charisma":13,"baseatk":3,"cmb":5,"cmd":18,"feats":[{"feat":"Skill Focus (Perception)"},{"feat":"Skill Focus (Perform sing)"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":8},{"skill":"Bluff","value":13},{"skill":"Diplomacy","value":5},{"skill":"Disguise","value":5},{"skill":"Knowledge (local)","value":5},{"skill":"Knowledge (nature)","value":5},{"skill":"Linguistics","value":4},{"skill":"Perception","value":12},{"skill":"Perform (dance)","value":8},{"skill":"Perform (sing)","value":13},{"skill":"Perform (string)","value":6},{"skill":"Sense Motive","value":13},{"skill":"Stealth","value":10}],"languages":["Common","Skald","Sylvan","Varisian"],"sq":["bardic knowledge +1","versatile performance (sing)"],"gear":"light crossbow with 10 bolts, ice floe elixir, entertainer's outfit, white hooded cloak, opal necklace (worth 500 gp), 14 gp, potion of cure moderate wounds, potions of undetectable alignment (2)","before_combat":"Mierul drinks a potion of undetectable alignment before approaching the party's camp.","during_combat":"If attacked, Mierul uses her bardic performance to inspire courage, then casts chord of shards. Thereafter, she casts flame blade or uses her natural claws backed with numbing cold to attack her enemies.","morale":"Mierul is a coward at heart, not a warrior. If reduced to 10 hit points or fewer, she flees into the winter storm.","source":"AP 67, Pathfinder RPG Bestiary 2 125 and page 72"},{"name":"Raven Swarm","cr":3,"xp":800,"race":"Raven Swarm","age_category":"Adult","alignment":"N","size":"Tiny","type":"animal","sub_types":["swarm"],"init":2,"senses":["low-light vision","scent"],"ac":14,"ac_touch":14,"ac_flat_footed":12,"ac_mods":"+2 Dex, +2 size","hp":30,"hd":"4d8+12","hd_value":4,"fort":6,"ref":6,"will":3,"defensive_abilities":["half damage from piercing and slashing weapons","swarm traits"],"speed":[{"type":"fly","speed":40,"maneuverability":"average"},{"type":"land","speed":10}],"melee":"swarm (1d6 plus eye-rake)","space":"10 ft.","reach":"0 ft.","special_attacks":[{"type":"distraction","details":"DC 14"},{"type":"eye-rake"}],"strength":2,"dexterity":15,"constitution":14,"intelligence":2,"wisdom":15,"charisma":7,"baseatk":3,"feats":[{"feat":"Skill Focus (Perception)"},{"feat":"Toughness"}],"skills":[{"skill":"Fly","value":10},{"skill":"Perception","value":11}],"special_abilities":[{"type":"Eye-Rake","kind":"Ex","details":"Any living creature damaged by a raven swarm must succeed at a DC 14 Reflex save or be blinded as the swarm scratches and tears at the victim's eyes. The blindness lasts for 1d4 days or until healed with remove blindness/deafness or a successful DC 20 Heal check. The save DC is Constitution-based."}],"during_combat":"The ravens swarm around as many targets as possible, scratching at opponents' eyes to maim and blind them.","morale":"If reduced to 15 hit points or fewer, the raven swarm disperses.","source":"AP 67, Tome of Horrors Complete 584"},{"name":"Pale Tower Guard","cr":0.3333,"xp":135,"race":"human","age_category":"Adult","classes":[{"class":"warrior","level":1}],"alignment":"LE","size":"Medium","type":"humanoid","sub_types":["human"],"init":1,"ac":16,"ac_touch":11,"ac_flat_footed":15,"ac_mods":"+4 armor, +1 Dex, +1 shield","hp":9,"hd":"1d10+4","hd_value":1,"fort":3,"ref":1,"will":0,"speed":[{"type":"land","speed":30}],"melee":"cold iron longsword +3 (1d8+1/19-20) or dagger +2 (1d4+1/19-20)","ranged":"light crossbow +2 (1d8/19-20)","space":"5 ft.","reach":"5 ft.","strength":13,"dexterity":12,"constitution":12,"intelligence":8,"wisdom":11,"charisma":9,"baseatk":1,"cmb":2,"cmd":13,"feats":[{"feat":"Toughness"},{"feat":"Weapon Focus (longsword)"}],"skills":[{"skill":"Intimidate","value":3},{"skill":"Perception","value":1},{"skill":"Profession (soldier)","value":4}],"languages":["Skald"],"gear":"chain shirt, light steel shield, cold iron longsword, dagger, light crossbow with 10 bolts, cold-weather outfit, 15 gp, potion of endure elements","during_combat":"The guards team up to provide flanking bonuses or use aid another actions to improve one another's attacks or AC.","morale":"The guards fight to the death.","source":"AP 67"},{"name":"Sergeant Volan Sertane","cr":2,"xp":600,"race":"Human (Ulfen)","gender":"Male","age_category":"Adult","classes":[{"class":"fighter","level":2},{"class":"ranger","level":1}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":2,"ac":17,"ac_touch":12,"ac_flat_footed":15,"ac_mods":"+4 armor, +2 Dex, +1 shield","hp":25,"hd":"3d10+5","hd_value":3,"fort":6,"ref":4,"will":2,"save_mods":"Will: +1 vs. fear","defensive_abilities":["bravery +1"],"speed":[{"type":"land","speed":30}],"melee":"mwk cold iron longsword +5 (1d8+2/19-20), light spiked shield +3 (1d4+1) or mwk cold iron longsword +7 (1d8+3/19-20) or dagger +5 (1d4+3/19-20)","ranged":"mwk light crossbow +6 (1d8/19-20)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"favored enemy","details":"humans +2"}],"strength":14,"dexterity":15,"constitution":12,"intelligence":10,"wisdom":10,"charisma":13,"baseatk":3,"cmb":5,"cmd":17,"feats":[{"feat":"Alertness"},{"feat":"Improved Shield Bash"},{"feat":"Iron Will"},{"feat":"Two-Weapon Fighting"},{"feat":"Weapon Focus (longsword)"}],"skills":[{"skill":"Handle Animal","value":5},{"skill":"Intimidate","value":7},{"skill":"Knowledge (local)","value":2},{"skill":"Knowledge (nature)","value":4},{"skill":"Perception","value":6},{"skill":"Ride","value":3},{"skill":"Sense Motive","value":4},{"skill":"Stealth","value":3},{"skill":"Survival","value":4}],"languages":["Skald"],"sq":["track +1","wild empathy +2"],"gear":"chain shirt, spiked light steel shield, dagger, mwk cold iron longsword, mwk light crossbow with 10 bolts, attentive mirror, cold-weather outfit, 24 gp, potions of cure light wounds (2), potion of endure elements, potion of interrogation (CL 4th), screaming bolts (2)","during_combat":"Volan attacks with his sword and spiked shield, targeting humans when possible to take advantage of his favored enemy bonus. Against heavily armored opponents, he switches to single attacks with his longsword instead, pausing only to drink a potion of cure light wounds to keep going.","morale":"If reduced to 10 hit points or fewer, Volan realizes the battle has turned against him. He takes the total defense action and uses a move action to retrieve his attentive mirror to warn Radosek about the danger the PCs pose before they can overwhelm him.","source":"AP 67"},{"name":"Animated Ice Dragon","cr":5,"xp":1600,"race":"Animated object","age_category":"Adult","alignment":"N","size":"Large","type":"construct","init":-1,"senses":["darkvision 60 ft.","low-light vision"],"ac":18,"ac_touch":8,"ac_flat_footed":18,"ac_mods":"-1 Dex, +10 natural, -1 size","hp":52,"hd":"4d10+30","hd_value":4,"fort":1,"ref":0,"will":-4,"defensive_abilities":["hardness 0"],"immunities":["cold","construct traits"],"weaknesses":["vulnerable to fire"],"speed":[{"type":"fly","speed":30,"maneuverability":"clumsy"},{"type":"land","speed":30}],"melee":"2 slams +9 (1d8+6)","space":"10 ft.","reach":"10 ft.","strength":22,"dexterity":8,"wisdom":1,"charisma":1,"baseatk":4,"cmb":11,"cmd":20,"skills":[{"skill":"Fly","value":-11}],"sq":["Construction Points (additional attack, additional movement [fly], ice)"],"special_abilities":[{"type":"Construction Points Ice","kind":"Ex, 1 CP","details":": The object is made of ice. Its hardness is reduced to 0, and it gains vulnerability to fire and immunity to cold."}],"during_combat":"The animated statue moves at the direction of Radosek, charging from the sky if allowed to fly. It otherwise slams its opponents, seeking to grapple and pin anyone Radosek deems especially dangerous.","morale":"The statue fights until destroyed.","source":"AP 67, Pathfinder RPG Bestiary 14"},{"name":"Captain Hestrig Orlov","cr":4,"xp":1200,"race":"Human (Ulfen)","gender":"Female","age_category":"Adult","classes":[{"class":"fighter","level":2},{"class":"sorcerer","level":3}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":1,"ac":17,"ac_touch":12,"ac_flat_footed":15,"ac_mods":"+4 armor, +1 Dex, +1 dodge, +1 natural","hp":38,"hd":"2d10+3d6+13","hd_value":5,"fort":7,"ref":3,"will":3,"save_mods":"Will: +1 vs. fear","defensive_abilities":["bravery +1"],"resists":["cold 5"],"speed":[{"type":"land","speed":30}],"melee":"+1 greatsword +8 (2d6+5/19-20) or 2 claws +6 (1d4+3)","ranged":"mwk throwing axe +5 (1d6+3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"claws","details":"2, 1d4+3, 5 rounds/day"}],"spellsknown_caster":"sorcerer","spellsknown_caster_level":3,"spellsknown_concentration":5,"spellsknown":[{"spell_level":1,"spell_slots":6,"spells":[{"spell":"enlarge person"},{"spell":"mage armor"},{"spell":"magic missile"},{"spell":"snowball"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"light"},{"spell":"mage hand"},{"spell":"ray of frost"},{"spell":"read magic"}]}],"bloodline":"draconic (white)   *See page 73.","strength":16,"dexterity":13,"constitution":14,"intelligence":10,"wisdom":8,"charisma":14,"baseatk":3,"cmb":6,"cmd":18,"feats":[{"feat":"Cleave"},{"feat":"Combat Casting"},{"feat":"Dodge"},{"feat":"Eschew Materials"},{"feat":"Power Attack"},{"feat":"Shield of Swings"},{"feat":"Weapon Focus (greatsword)"}],"skills":[{"skill":"Intimidate","value":8},{"skill":"Knowledge (arcana)","value":4},{"skill":"Perception","value":7},{"skill":"Profession (soldier)","value":5},{"skill":"Ride","value":5},{"skill":"Spellcraft","value":4},{"skill":"Use Magic Device","value":6}],"languages":["Skald"],"sq":["bloodline arcana (cold energy spells deal +1 damage per die)"],"gear":"dagger, mwk greatsword, mwk throwing axe, cloak of resistance +1, key to chest in area Q16, teleporter key (to area Q15), 65 gp, elixir of fire breath, potions of cure moderate wounds (2), scroll of magic weapon","before_combat":"If alerted to the PCs' presence, Hestrig casts mage armor and magic weapon from her scroll to prepare for battle.","during_combat":"If she has enough room, Hestrig casts enlarge person during a fight, sweeping her greatsword in giant arcs with her improved reach to use Power Attack and Cleave against her opponents, alternating attacks with spells such as snowball or magic missile. If faced with a formidable foe, she changes strategy and uses her Shield of Swings feat to increase her AC. Hestrig is loathe to use her elixir of fire breath, as she acquired it as an insurance policy against treachery from the ice troll Bordegga or the cold fey in the tower.","morale":"Hestrig lacks the wisdom to flee or surrender. She fights to the death.","base_statistics":"Without her spells, Hestrig's statistics are AC 13, touch 12, flat-footed 11; Melee mwk greatsword +8 (2d6+4/19-20).","source":"AP 67"},{"name":"Animated Ice Nymph","cr":3,"xp":800,"race":"Animated object","age_category":"Adult","alignment":"N","size":"Medium","type":"construct","init":0,"senses":["darkvision 60 ft.","low-light vision"],"ac":14,"ac_touch":10,"ac_flat_footed":14,"ac_mods":"+4 natural","hp":36,"hd":"3d10+20","hd_value":3,"fort":1,"ref":1,"will":-4,"defensive_abilities":["hardness 0"],"immunities":["cold","construct traits"],"weaknesses":["vulnerable to fire"],"speed":[{"type":"land","speed":30}],"melee":"2 slams +5 (1d6+2)","space":"5 ft.","reach":"5 ft.","strength":14,"dexterity":10,"wisdom":1,"charisma":1,"baseatk":3,"cmb":5,"cmd":15,"sq":["Construction Points (additional attack, ice)"],"special_abilities":[{"type":"Construction Points Ice","kind":"Ex, 1 CP","details":": The object is made of ice. Its hardness is reduced to 0, and it gains vulnerability to fire and immunity to cold."}],"source":"AP 67, Pathfinder RPG Bestiary 14"},{"name":"Jairess Sonn","cr":2,"xp":600,"race":"sylph","gender":"Female","age_category":"Adult","classes":[{"class":"cleric of Gozreh","level":3}],"alignment":"CN","size":"Medium","type":"outsider","sub_types":["native"],"init":2,"senses":["darkvision 60 ft."],"ac":15,"ac_touch":12,"ac_flat_footed":13,"ac_mods":"+2 armor, +2 Dex, +1 shield","hp":20,"hd":"3d8+3","hd_value":3,"fort":3,"ref":3,"will":5,"resists":["electricity 5"],"speed":[{"type":"land","speed":30}],"melee":"mwk shortspear +3 (1d6-1) or dagger +1 (1d4-1/19-20)","ranged":"mwk shortspear +6 (1d6-1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"channel positive energy","details":"5/day, DC 13, 2d6"}],"spell_like_abilities_caster_level":3,"spell_like_abilities_concentration":5,"spell_like_abilities":[{"frequency":"at-will","spells":[{"spell":"speak with animals","details":"6 rounds/day"}]},{"frequency":"5/day","spells":[{"spell":"lightning arc","details":"1d6+1 electricity"}]}],"spellsprepared_caster":"cleric","spellsprepared_caster_level":3,"spellsprepared_concentration":5,"spellsprepared":[{"spell_level":2,"spell_slots":3,"spells":[{"spell":"hold person"},{"spell":"sound burst"},{"spell":"wind wall","type":"domain"}]},{"spell_level":1,"spell_slots":4,"spells":[{"spell":"divine favor"},{"spell":"doom"},{"spell":"endure elements"},{"spell":"obscuring mist","type":"domain"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"detect magic"},{"spell":"guidance"},{"spell":"resistance"},{"spell":"virtue"}]}],"spelldomains":"Air, Animal","strength":8,"dexterity":15,"constitution":10,"intelligence":12,"wisdom":15,"charisma":14,"baseatk":2,"cmb":1,"cmd":13,"feats":[{"feat":"Selective Channeling"},{"feat":"Weapon Focus (shortspear)"}],"skills":[{"skill":"Acrobatics","value":3},{"skill":"Diplomacy","value":6},{"skill":"Fly","value":3},{"skill":"Knowledge (nature)","value":5},{"skill":"Knowledge (religion)","value":5},{"skill":"Perception","value":3},{"skill":"Sense Motive","value":6}],"languages":["Common","Auran","Skald"],"sq":["air affinity"],"gear":"leather armor, light wooden shield, dagger, mwk shortspear, teleporter key (to area Q13), wooden holy symbol of Gozreh, silver necklace with star-shaped ice diamond pendant (worth 500 gp), 84 gp, potion of fly, scroll of returning weapon","before_combat":"Unlike many of the Pale Tower's inhabitants, Jairess has trouble weathering the cold, so she casts endure elements on herself every day.","during_combat":"Jairess directs her ravens to swarm opponents on the first round of battle while she drinks her potion of fly (increasing her Fly skill to +12) and rises into the air. She then casts wind wall to defend against ranged attacks, followed by spells such as hold person and sound burst to keep enemies from avoiding the raven swarm. If she must fight, Jairess casts returning weapon from her scroll on her shortspear. If she or the ravens become significantly injured, she casts obscuring mist and channels positive energy, excluding nearby adversaries with her Selective Channeling feat.","morale":"Once she exhausts her offensive spells and healing powers, Jairess surrenders, calling her surviving birds back to her. If the raven swarm is slain, Jairess avenges them by fighting to the death.","source":"AP 67, Pathfinder RPG Bestiary 2 258"},{"name":"Nadya Petska","cr":2,"xp":600,"race":"Human (Ulfen)","gender":"Female","age_category":"Adult","classes":[{"class":"ranger","level":3}],"alignment":"CG","size":"Medium","type":"humanoid","sub_types":["human"],"init":2,"ac":15,"ac_touch":12,"ac_flat_footed":13,"ac_mods":"+3 armor, +2 Dex","hp":24,"hd":"3d10+3","hd_value":3,"fort":4,"ref":5,"will":0,"speed":[{"type":"land","speed":30}],"melee":"handaxe +3 (1d6+1/3) and light pick +3 (1d4/4) or handaxe +5 (1d6+1/x3) or light pick +5 (1d4+1/x4)","ranged":"composite longbow +5 (1d8+1/x3)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"favored enemy","details":"animals +2"}],"strength":12,"dexterity":15,"constitution":13,"intelligence":12,"wisdom":8,"charisma":14,"baseatk":3,"cmb":4,"cmd":16,"feats":[{"feat":"Endurance"},{"feat":"Point-Blank Shot"},{"feat":"Skill Focus (Survival)"},{"feat":"Two-Weapon Fighting"},{"feat":"Weapon Finesse"}],"skills":[{"skill":"Acrobatics","value":5},{"skill":"Climb","value":5},{"skill":"Handle Animal","value":6},{"skill":"Heal","value":5},{"skill":"Knowledge (geography)","value":7},{"skill":"Knowledge (local)","value":4},{"skill":"Knowledge (nature)","value":7},{"skill":"Perception","value":5},{"skill":"Ride","value":6},{"skill":"Stealth","value":8},{"skill":"Survival","value":8}],"languages":["Common","Skald"],"sq":["favored terrain (cold +2)","track +1","wild empathy +5"],"gear":"mwk studded leather, composite longbow (+1 Str) with 20 arrows, dagger, handaxe, light pick, snowshoes of northern pursuit, backpack, bedroll, cold-weather outfit, flint and steel, hooded lantern, oil (2), rations (10 days), tindertwigs (3), traveler's outfit, waterskin, winter blanket, 36 gp, 27 sp, 41 cp, potion of cure moderate wounds, alchemist's fire (2)","during_combat":"Nadya tries to keep her distance in battle, firing her bow at adversaries before they can close on her. When faced with more dangerous foes, especially those attuned to cold, Nadya hurls a flask of alchemist's fire to hinder them.","morale":"Nadya fights with conviction, but recognizes overwhelming odds and surrenders when necessary. In the face of truly uncompromising evil, she fights to the death.","source":"AP 67"},{"name":"Radosek Pavril","cr":5,"xp":1600,"race":"Human (Taldan)","gender":"Male","age_category":"Adult","classes":[{"class":"witch","level":5,"archetype":"winter witch"}],"alignment":"NE","size":"Medium","type":"humanoid","sub_types":["human"],"init":2,"ac":18,"ac_touch":13,"ac_flat_footed":16,"ac_mods":"+4 armor, +1 deflection, +2 Dex, +1 natural","hp":50,"hd":"5d6+30","hd_value":5,"fort":4,"ref":4,"will":8,"resists":["cold 5"],"speed":[{"type":"land","speed":30}],"melee":"icicle wand +3 (1d4/19-20 plus 1 cold)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"hexes","details":"flight [ feather fall at will, levitate 1/day, fly 5 minutes/day], frozen caress"},{"type":"ice magic"}],"spell_like_abilities_caster_level":5,"spell_like_abilities_concentration":4,"spell_like_abilities":[{"frequency":"constant","spells":[{"spell":"endure elements","details":"cold only"}]}],"spellsprepared_caster":"witch","spellsprepared_caster_level":5,"spellsprepared_concentration":8,"spellsprepared":[{"spell_level":3,"spell_slots":2,"spells":[{"spell":"Irriseni mirror sight"},{"spell":"summon monster III"}]},{"spell_level":2,"spell_slots":3,"spells":[{"spell":"blindness/deafness"},{"spell":"false life"},{"spell":"flurry of snowballs"}]},{"spell_level":1,"spell_slots":4,"spells":[{"spell":"chill touch"},{"spell":"frostbite"},{"spell":"ill omen"},{"spell":"mage armor"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"daze"},{"spell":"detect magic"},{"spell":"ray of frost"},{"spell":"touch of fatigue"}]}],"patron":"winter","strength":10,"dexterity":14,"constitution":14,"intelligence":17,"wisdom":12,"charisma":8,"baseatk":2,"cmb":2,"cmd":15,"feats":[{"feat":"Alertness","type":"bonus"},{"feat":"Craft Magic Arms and Armor"},{"feat":"Craft Wand"},{"feat":"Iron Will"},{"feat":"Toughness"}],"skills":[{"skill":"Craft (alchemy)","value":10},{"skill":"Fly","value":8},{"skill":"Intimidate","value":7},{"skill":"Knowledge (arcana)","value":10},{"skill":"Knowledge (local)","value":5},{"skill":"Knowledge (nature)","value":7},{"skill":"Knowledge (nobility)","value":5},{"skill":"Knowledge (planes)","value":7},{"skill":"Perception","value":3},{"skill":"Sense Motive","value":3},{"skill":"Spellcraft","value":10},{"skill":"Survival","value":4},{"skill":"Swim","value":4},{"skill":"Use Magic Device","value":6}],"languages":["Common","Giant","Skald","Sylvan"],"sq":["cold flesh","exceptional resources","witch's familiar (goat named Valstoi)"],"special_abilities":[{"type":"Exceptional Resources","kind":"Ex","details":"As Nazhena Vasilliovna's apprentice, Radosek has access to all of the resources of the Pale Tower, granting him the same wealth as a PC. This increases his CR by 1."}],"gear":"amulet of natural armor +1, cloak of resistance +1, ring of protection +1, spell component pouch, icicle wand (42 charges), potions of cure moderate wounds (2), scroll of animate objects","before_combat":"Radosek always casts false life and mage armor before battle.","during_combat":"Radosek casts summon monster III on the first round of combat, using the cauldron of overwhelming allies in area Q20 to summon 2d3 Small ice elementals to surround and protect himself. He then uses his flight hex to levitate or fly above the fray, conjuring ice spears with his icicle wand or casting blindness/deafness on anyone targeting him with ranged attacks or spells. Thereafter, Radosek resorts to his touch spells, spending a swift action to infuse them with his frozen caress hex, either delivering hexes himself or relying on his familiar, Valstoi, to do so.","morale":"If reduced to 15 or fewer hit points, Radosek flees, either through the room's windows using his flight hex, or into area Q23 to use the ice crystal teleporter. In either case, he retreats to the courtyard (area Q2), where he rallies any remaining defenders in the Pale Tower. Thereafter, Radosek fights to the death.","source":"AP 67, Pathfinder RPG Advanced Player's Guide 65, Pathfinder Campaign Setting: Inner Sea Magic 43"},{"name":"Valstoi","xp":0,"race":"goat familiar","gender":"Female","age_category":"Adult","alignment":"N","size":"Small","type":"magical beast","sub_types":["augmented animal"],"init":1,"senses":["low-light vision"],"ac":16,"ac_touch":12,"ac_flat_footed":15,"ac_mods":"+1 Dex, +4 natural, +1 size","hp":20,"hd":"5d10+5","hd_value":5,"fort":3,"ref":3,"will":4,"defensive_abilities":["improved evasion"],"speed":[{"type":"land","speed":30}],"melee":"gore +4 (1d4+1)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"deliver touch spells"}],"strength":12,"dexterity":13,"constitution":12,"intelligence":8,"wisdom":11,"charisma":5,"baseatk":2,"cmb":2,"cmd":13,"cmd_special":"17 vs. trip","feats":[{"feat":"Nimble Moves"}],"skills":[{"skill":"Acrobatics","value":1,"special":"+4 when jumping"},{"skill":"Climb","value":5},{"skill":"Craft (alchemy)","value":3},{"skill":"Fly","value":9},{"skill":"Intimidate","value":2},{"skill":"Knowledge (arcana)","value":3},{"skill":"Knowledge (local)","value":1},{"skill":"Knowledge (nature)","value":0},{"skill":"Knowledge (nobility)","value":1},{"skill":"Knowledge (planes)","value":0},{"skill":"Spellcraft","value":3},{"skill":"Survival","value":0,"special":"+4 to find food"},{"skill":"Use Magic Device","value":1}],"sq":["alertness","empathic link","share spells","speak with master","store spells"],"special_abilities":[{"type":"Stored Spells","details":"All cantrips and prepared spells plus: 1st-cause fear, charm person, cure light wounds, icicle dagger, sleep, summon monster I, unshakable chill; 2nd-cure moderate wounds, resist energy (cold only), scare; 3rd-bestow curse, ice spears."}],"source":"AP 67, Pathfinder RPG Bestiary 3 112"},{"name":"Murgmo","cr":2,"xp":600,"race":"Goblin","gender":"Female","age_category":"Adult","classes":[{"class":"oracle","level":3}],"alignment":"NE","size":"Small","type":"humanoid","sub_types":["goblinoid"],"init":5,"senses":["darkvision 60 ft."],"ac":16,"ac_touch":12,"ac_flat_footed":15,"ac_mods":"+4 armor, +1 Dex, +1 size","hp":23,"hd":"3d8+6","hd_value":3,"fort":2,"ref":2,"will":5,"save_mods":"+4 vs. disease","speed":[{"type":"land","speed":30}],"melee":"mwk longspear +3 (1d6-1/x3)","space":"5 ft.","reach":"5 ft.","spellsknown_caster":"oracle","spellsknown_caster_level":3,"spellsknown_concentration":4,"spellsknown":[{"spell_level":1,"spell_slots":6,"spells":[{"spell":"bane"},{"spell":"burning hands"},{"spell":"cause fear"},{"spell":"doom"},{"spell":"inflict light wounds"}]},{"spell_level":0,"spell_slots":99,"spells":[{"spell":"bleed"},{"spell":"create water"},{"spell":"detect magic"},{"spell":"light"},{"spell":"resistance"}]}],"mystery":"flame","strength":8,"dexterity":12,"constitution":12,"intelligence":13,"wisdom":14,"charisma":13,"baseatk":2,"cmb":0,"cmd":11,"feats":[{"feat":"Combat Casting"},{"feat":"Improved Initiative"}],"skills":[{"skill":"Acrobatics","value":6},{"skill":"Climb","value":4},{"skill":"Heal","value":8},{"skill":"Sense Motive","value":8},{"skill":"Spellcraft","value":7},{"skill":"Stealth","value":8}],"languages":["Common","Goblin"],"sq":["oracle's curse (wasting)","revelations (burning magic, fire breath [3d4, 1/day, DC 12])"],"gear":"masterwork chain shirt, masterwork longspear, potion of cure light wounds, acid (2)","before_combat":"If she has time to prepare for an encounter against the PCs, Murgmo gets in a tactical position so she can use her burning hands spell and fire breath ability to damage the PCs and avoid her own allies.","during_combat":"Murgmo relies on her Goblin warriors to do most of the heavy lifting in combat while she uses spells like doom to hinder the PCs and her fire breath ability to damage them. She drinks her potion of cure light wounds if her hit points drop to fewer than 10.","morale":"Murgmo is determined to find the sword of Zog, and fights to the death.","source":"Thornkeep, Pathfinder RPG Bestiary 156, Pathfinder RPG Advanced Player's Guide 42"},{"name":"Snarltongue","cr":4,"xp":1200,"race":"Goblin","gender":"Male","age_category":"Adult","classes":[{"class":"barbarian","level":4}],"alignment":"CE","size":"Small","type":"humanoid","sub_types":["goblinoid"],"init":3,"senses":["darkvision 60 ft."],"ac":16,"ac_touch":12,"ac_flat_footed":13,"ac_mods":"+4 armor, +3 Dex, -2 rage, +1 size","hp":55,"hd":"4d12+24","hd_value":4,"hp_mods":"fast healing 2","fort":8,"ref":4,"will":4,"defensive_abilities":["trap sense +1","uncanny dodge"],"speed":[{"type":"land","speed":30}],"melee":"+1 battleaxe +10 (1d6+6/x3)","ranged":"alchemist's fire +8 ranged touch (1d6 fire)","space":"5 ft.","reach":"5 ft.","special_attacks":[{"type":"alchemical enhancements"},{"type":"rage","details":"12 rounds/day"},{"type":"rage powers","details":"powerful blow +2, renewed vigor [1d8+6 hp]"}],"strength":18,"dexterity":17,"constitution":18,"intelligence":8,"wisdom":12,"charisma":8,"baseatk":4,"cmb":7,"cmd":18,"feats":[{"feat":"Power Attack"},{"feat":"Toughness"}],"skills":[{"skill":"Acrobatics","value":5},{"skill":"Handle Animal","value":6},{"skill":"Intimidate","value":6},{"skill":"Ride","value":4},{"skill":"Stealth","value":10}],"languages":["Goblin"],"sq":["fast movement"],"special_abilities":[{"type":"Alchemical Enhancements","kind":"Ex","details":"The tubes installed into Snarltongue's head grant him several exceptional powers. The purple tube contains a fluid that allows Snarltongue to become invisible as per the spell for up to 10 rounds per day. These rounds don't have to be consecutive. Using this ability is a move action. The green tube contains a liquid that gives Snarltongue fast healing 2. This ability is always active. When he uses rounds of rage, the fluid in the red tube begins to drain (this fluid doesn't grant him any additional rage powers or rounds of rage)."}],"gear":"hide armor, +1 battleaxe, alchemist's fire (3)","before_combat":"If the PCs venture through the gallery up above, Snarltongue merely observes them from the shadows under the table, which grant him a +4 circumstance bonus on his Stealth check. If the PCs find their way down, he uses his ability to turn invisible and closes in to attack, using his dire rats to distract the rest of the party.","during_combat":"Snarltongue closes with his enemies before becoming visible and flying into a rage. He attacks with reckless abandon and, given the chance, tosses alchemist's fire at spellcasters to distract them from casting spells.","morale":"The Goblin fears only his master's wrath. As such, he fights to the death.","base_statistics":"When not raging, Snarltongue's statistics are AC 18, touch 14, flat-footed 15; hp 47; Fort +6, Will +2; +1 battleaxe +8 (1d6+3/x3); Str 14, Con 14; CMB +5, CMD 18.","source":"Thornkeep, Pathfinder RPG Bestiary 156"}];
